//! Round-trip parser for MatRust App Designer generated `.m` files.

use super::codegen::{
    BODY_END_PREFIX, BODY_MARKER_TAG, BODY_START_PREFIX, GENERATED_HEADER_MARKER,
};
use super::{
    AppCallback, AppComponent, AppComponentKind, AppFigure, AppGridLayout, AppGridTrack,
    AppLoadResult, AppModel, AppPrivateProperty, AppValue, AppValueKind, GridSpanSpec,
};
use std::collections::BTreeMap;

/// Load `.m` source: returns `Editable(AppModel)` if it was generated by
/// MatRust App Designer and parses cleanly, otherwise `ReadOnlyCode` with a
/// clear explanation.
pub fn load_m_source(source: &str) -> AppLoadResult {
    if !source.contains(GENERATED_HEADER_MARKER) {
        return AppLoadResult::ReadOnlyCode {
            code: source.to_string(),
            reason: "This file was not generated by MatRust App Designer and is opened read-only as code.".into(),
        };
    }
    match parse_generated_m(source) {
        Ok(model) => AppLoadResult::Editable(model),
        Err(err) => AppLoadResult::ReadOnlyCode {
            code: source.to_string(),
            reason: format!(
                "This file could not be parsed as a MatRust App Designer layout ({err}) and is opened read-only as code."
            ),
        },
    }
}

/// Parse a `.m` file produced by `generate_m` back into an `AppModel`.
pub fn parse_generated_m(source: &str) -> Result<AppModel, String> {
    let lines: Vec<&str> = source
        .split('\n')
        .map(|l| l.strip_suffix('\r').unwrap_or(l))
        .collect();

    if !lines.iter().any(|l| l.trim() == GENERATED_HEADER_MARKER) {
        return Err("missing MatRust App Designer header marker".into());
    }

    // 1. Class name
    let class_name = lines
        .iter()
        .find_map(|l| {
            let t = l.trim();
            let rest = t.strip_prefix("classdef ")?;
            let (name, super_part) = rest.split_once('<')?;
            if super_part.trim() == "matlab.apps.AppBase" {
                Some(name.trim().to_string())
            } else {
                None
            }
        })
        .ok_or("missing `classdef <Name> < matlab.apps.AppBase` header")?;

    // 2. Parse properties blocks, method bodies, and createComponents lines.
    let mut figure = AppFigure::default();
    let mut figure_seen = false;
    let mut grid: Option<AppGridLayout> = None;
    let mut components: Vec<AppComponent> = Vec::new();
    let mut private_properties: Vec<AppPrivateProperty> = Vec::new();
    let mut bodies: BTreeMap<String, String> = BTreeMap::new();
    let mut callback_order: Vec<String> = Vec::new();
    let mut startup_seen = false;
    let mut create_lines: Vec<&str> = Vec::new();

    let mut i = 0usize;
    while i < lines.len() {
        let trimmed = lines[i].trim();

        if trimmed == "properties (Access = public)" {
            i += 1;
            while i < lines.len() && lines[i].trim() != "end" {
                let line = lines[i].trim();
                if !line.is_empty() && !line.starts_with('%') {
                    let mut parts = line.split_whitespace();
                    let prop_name = parts
                        .next()
                        .ok_or("malformed public property declaration")?;
                    let prop_type = parts
                        .next()
                        .ok_or("missing type on public property declaration")?;
                    if prop_type == "matlab.ui.Figure" {
                        figure.name = prop_name.to_string();
                        figure_seen = true;
                    } else if prop_type == "matlab.ui.container.GridLayout" {
                        grid = Some(AppGridLayout::new(prop_name, 1, 1));
                    } else if let Some(kind) = AppComponentKind::from_matlab_class_name(prop_type) {
                        components.push(AppComponent::new(prop_name, kind));
                    } else {
                        return Err(format!("unknown component type '{prop_type}'"));
                    }
                }
                i += 1;
            }
        } else if trimmed == "properties (Access = private)" {
            i += 1;
            while i < lines.len() && lines[i].trim() != "end" {
                let line = lines[i].trim();
                if !line.is_empty() && !line.starts_with('%') {
                    if let Some((lhs, rhs)) = line.split_once('=') {
                        private_properties.push(AppPrivateProperty {
                            name: lhs.trim().to_string(),
                            default_expr: Some(rhs.trim().to_string()),
                        });
                    } else {
                        private_properties.push(AppPrivateProperty {
                            name: line.to_string(),
                            default_expr: None,
                        });
                    }
                }
                i += 1;
            }
        } else if let Some(rest) = trimmed.strip_prefix(BODY_START_PREFIX)
            && let Some(method_name) = rest.strip_suffix(']')
        {
            let method_name = method_name.trim().to_string();
            if bodies.contains_key(&method_name) {
                return Err(format!("duplicate body marker for '{method_name}'"));
            }
            let end_marker = format!("{BODY_END_PREFIX}{method_name}]");
            i += 1;
            let mut body_lines: Vec<&str> = Vec::new();
            let mut found_end = false;
            while i < lines.len() {
                if lines[i].trim() == end_marker {
                    found_end = true;
                    break;
                }
                if is_marker_like(lines[i]) {
                    return Err(format!(
                        "unpaired or nested body marker inside '{method_name}': {}",
                        lines[i].trim()
                    ));
                }
                let raw = lines[i];
                let unindented = raw.strip_prefix("            ").unwrap_or(raw);
                body_lines.push(unindented);
                i += 1;
            }
            if !found_end {
                return Err(format!("unterminated body block for '{method_name}'"));
            }
            if method_name == "startupFcn" {
                startup_seen = true;
            } else {
                callback_order.push(method_name.clone());
            }
            bodies.insert(method_name, body_lines.join("\n"));
        } else if is_marker_like(trimmed) {
            return Err(format!("body marker without a matching start: {trimmed}"));
        } else if trimmed == "function createComponents(app)" {
            i += 1;
            while i < lines.len() && lines[i].trim() != "end" {
                let line = lines[i].trim();
                if !line.is_empty() && !line.starts_with('%') {
                    create_lines.push(line);
                }
                i += 1;
            }
        }
        i += 1;
    }

    if !figure_seen {
        return Err("missing UIFigure property".into());
    }

    // 3. Parse createComponents statements.
    let mut callback_bindings: BTreeMap<String, (String, String)> = BTreeMap::new();
    let default_parent = grid
        .as_ref()
        .map(|g| g.name.as_str())
        .unwrap_or(figure.name.as_str())
        .to_string();

    for stmt in create_lines {
        let stmt = stmt.strip_suffix(';').unwrap_or(stmt).trim();
        let Some((lhs, rhs)) = stmt.split_once('=') else {
            continue;
        };
        let lhs = lhs.trim();
        let rhs = rhs.trim();
        let Some(target) = lhs.strip_prefix("app.") else {
            continue;
        };

        // Direct construction: `app.Comp = ui...(app.Parent, ...)`
        if !target.contains('.') {
            if let Some(comp) = components.iter_mut().find(|c| c.name == target)
                && let Some(parent_name) = parse_constructor_parent(rhs)
            {
                if parent_name != default_parent {
                    comp.parent = Some(parent_name);
                } else {
                    comp.parent = None;
                }
            }
            continue;
        }

        // Property assignment: `app.<Target>.<PropPath> = <rhs>`
        let Some((obj_name, prop_path)) = target.split_once('.') else {
            continue;
        };

        // Callback binding? `createCallbackFcn(app, @Method, true)`
        if let Some(method_name) = parse_create_callback_fcn(rhs) {
            callback_bindings.insert(method_name, (obj_name.to_string(), prop_path.to_string()));
            continue;
        }

        if obj_name == figure.name {
            match prop_path {
                "Position" => figure.position = parse_pos4(rhs)?,
                "Name" => figure.title = parse_matlab_char(rhs)?,
                "Visible" => {}
                _ => {}
            }
            continue;
        }

        if let Some(ref mut g) = grid
            && obj_name == g.name
        {
            match prop_path {
                "RowHeight" => g.row_height = parse_grid_tracks(rhs)?,
                "ColumnWidth" => g.column_width = parse_grid_tracks(rhs)?,
                _ => {}
            }
            continue;
        }

        if let Some(comp) = components.iter_mut().find(|c| c.name == obj_name) {
            match prop_path {
                "Layout.Row" => comp.grid_row = Some(parse_span(rhs)?),
                "Layout.Column" => comp.grid_column = Some(parse_span(rhs)?),
                "Position" => comp.position = parse_pos4(rhs)?,
                "Text" => comp.props.text = Some(parse_matlab_char(rhs)?),
                "Title" => comp.props.title = Some(parse_matlab_char(rhs)?),
                "Items" => comp.props.items = Some(parse_cellstr(rhs)?),
                "ColumnName" => comp.props.column_name = Some(parse_cellstr(rhs)?),
                "Limits" => comp.props.limits = Some(parse_limits(rhs)?),
                "Value" => {
                    let val = match comp.kind.value_kind() {
                        Some(AppValueKind::Number) => AppValue::Number(parse_number(rhs)?),
                        Some(AppValueKind::Text) => AppValue::Text(parse_matlab_char(rhs)?),
                        Some(AppValueKind::Bool) => AppValue::Bool(parse_bool(rhs)?),
                        Some(AppValueKind::Lines) => AppValue::Lines(parse_cellstr(rhs)?),
                        None => return Err(format!("unexpected Value on '{}'", comp.name)),
                    };
                    comp.props.value = Some(val);
                }
                _ => {}
            }
        }
    }

    // 4. Assemble callbacks in declaration order.
    let mut callbacks = Vec::new();
    for method_name in callback_order {
        let Some((component, event)) = callback_bindings.remove(&method_name) else {
            return Err(format!(
                "callback method '{method_name}' is not bound in createComponents"
            ));
        };
        let body = bodies.remove(&method_name).unwrap_or_default();
        callbacks.push(AppCallback {
            component,
            event,
            method_name,
            body,
        });
    }

    let startup_fcn = if startup_seen {
        Some(bodies.remove("startupFcn").unwrap_or_default())
    } else {
        None
    };

    Ok(AppModel {
        class_name,
        figure,
        grid,
        components,
        private_properties,
        startup_fcn,
        callbacks,
    })
}

/// A comment line carrying the region-marker tag (generated bodies never
/// contain one; codegen refuses them).
fn is_marker_like(line: &str) -> bool {
    let t = line.trim_start();
    t.starts_with('%') && t.contains(BODY_MARKER_TAG)
}

fn parse_constructor_parent(rhs: &str) -> Option<String> {
    let open = rhs.find('(')?;
    let close = rhs.rfind(')')?;
    if close <= open {
        return None;
    }
    let inside = rhs[open + 1..close].trim();
    let first = inside.split(',').next()?.trim();
    first.strip_prefix("app.").map(ToOwned::to_owned)
}

fn parse_create_callback_fcn(rhs: &str) -> Option<String> {
    let inner = rhs.strip_prefix("createCallbackFcn(")?.strip_suffix(')')?;
    let mut parts = inner.split(',');
    let _app = parts.next()?.trim();
    let handle = parts.next()?.trim();
    handle.strip_prefix('@').map(|s| s.trim().to_string())
}

fn parse_matlab_char(s: &str) -> Result<String, String> {
    let s = s.trim();
    if s.len() < 2 || !s.starts_with('\'') || !s.ends_with('\'') {
        return Err(format!("expected MATLAB char literal, got {s}"));
    }
    let inner = &s[1..s.len() - 1];
    let mut out = String::with_capacity(inner.len());
    let mut chars = inner.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch == '\'' {
            if chars.peek() == Some(&'\'') {
                chars.next();
                out.push('\'');
            } else {
                return Err(format!("unescaped quote in MATLAB char literal: {s}"));
            }
        } else {
            out.push(ch);
        }
    }
    Ok(out)
}

fn parse_cellstr(s: &str) -> Result<Vec<String>, String> {
    let s = s.trim();
    let inner = s
        .strip_prefix('{')
        .and_then(|r| r.strip_suffix('}'))
        .ok_or_else(|| format!("expected cell array literal, got {s}"))?
        .trim();
    if inner.is_empty() {
        return Ok(Vec::new());
    }
    let items = split_matlab_cell_elements(inner)?;
    items
        .into_iter()
        .map(|tok| parse_matlab_char(&tok))
        .collect()
}

fn split_matlab_cell_elements(inner: &str) -> Result<Vec<String>, String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut in_quote = false;
    let mut chars = inner.chars().peekable();
    while let Some(ch) = chars.next() {
        if in_quote {
            cur.push(ch);
            if ch == '\'' {
                if chars.peek() == Some(&'\'') {
                    cur.push(chars.next().unwrap());
                } else {
                    in_quote = false;
                }
            }
        } else if ch == '\'' {
            in_quote = true;
            cur.push(ch);
        } else if ch == ',' || ch == ';' {
            let trimmed = cur.trim();
            if !trimmed.is_empty() {
                out.push(trimmed.to_string());
            }
            cur.clear();
        } else {
            cur.push(ch);
        }
    }
    if in_quote {
        return Err("unterminated quote in cell array".into());
    }
    let trimmed = cur.trim();
    if !trimmed.is_empty() {
        out.push(trimmed.to_string());
    }
    Ok(out)
}

fn parse_grid_tracks(s: &str) -> Result<Vec<AppGridTrack>, String> {
    let s = s.trim();
    let inner = s
        .strip_prefix('{')
        .and_then(|r| r.strip_suffix('}'))
        .ok_or_else(|| format!("expected cell array for grid tracks, got {s}"))?
        .trim();
    let tokens = split_matlab_cell_elements(inner)?;
    let mut out = Vec::with_capacity(tokens.len());
    for tok in tokens {
        if tok.starts_with('\'') {
            let text = parse_matlab_char(&tok)?;
            if text.eq_ignore_ascii_case("fit") {
                out.push(AppGridTrack::Fit);
            } else if let Some(num) = text.strip_suffix('x').or_else(|| text.strip_suffix('X')) {
                let w = parse_number(num)?;
                out.push(AppGridTrack::Weight(w));
            } else {
                return Err(format!("invalid grid track '{text}'"));
            }
        } else {
            out.push(AppGridTrack::Pixels(parse_number(&tok)?));
        }
    }
    Ok(out)
}

fn parse_number(s: &str) -> Result<f64, String> {
    let s = s.trim();
    if s.eq_ignore_ascii_case("inf") || s.eq_ignore_ascii_case("+inf") {
        return Ok(f64::INFINITY);
    }
    if s.eq_ignore_ascii_case("-inf") {
        return Ok(f64::NEG_INFINITY);
    }
    s.parse::<f64>()
        .map_err(|_| format!("invalid number '{s}'"))
}

fn parse_bool(s: &str) -> Result<bool, String> {
    match s.trim() {
        "true" | "1" => Ok(true),
        "false" | "0" => Ok(false),
        other => Err(format!("invalid logical literal '{other}'")),
    }
}

fn parse_bracket_nums(s: &str) -> Result<Vec<f64>, String> {
    let inner = s
        .trim()
        .strip_prefix('[')
        .and_then(|r| r.strip_suffix(']'))
        .ok_or_else(|| format!("expected numeric vector '[...]', got {s}"))?;
    inner
        .split(|c: char| c.is_whitespace() || c == ',')
        .filter(|t| !t.is_empty())
        .map(parse_number)
        .collect()
}

fn parse_pos4(s: &str) -> Result<[f64; 4], String> {
    let v = parse_bracket_nums(s)?;
    if v.len() != 4 {
        return Err(format!("expected 4-element Position, got {s}"));
    }
    Ok([v[0], v[1], v[2], v[3]])
}

fn parse_limits(s: &str) -> Result<[f64; 2], String> {
    let v = parse_bracket_nums(s)?;
    if v.len() != 2 {
        return Err(format!("expected 2-element Limits, got {s}"));
    }
    Ok([v[0], v[1]])
}

fn parse_span(s: &str) -> Result<GridSpanSpec, String> {
    let s = s.trim();
    if s.starts_with('[') {
        let v = parse_bracket_nums(s)?;
        if v.len() != 2 || v[0] < 1.0 || v[1] < v[0] || v[0].fract() != 0.0 || v[1].fract() != 0.0 {
            return Err(format!("invalid grid span '{s}'"));
        }
        Ok(GridSpanSpec::Range(v[0] as usize, v[1] as usize))
    } else {
        let n = s
            .parse::<usize>()
            .map_err(|_| format!("invalid grid index '{s}'"))?;
        Ok(GridSpanSpec::Single(n))
    }
}
